use crate::aap::caps::state_read;

struct Node;

/// Minimal parser for a JSON array of strings. Returns None if the input
/// is not shaped like one.
fn parse_json_string_array(s: &str) -> Option<Vec<String>> {
    let s = s.trim();
    let inner = s.strip_prefix('[')?.strip_suffix(']')?;
    let mut out = Vec::new();
    let mut chars = inner.chars().peekable();
    loop {
        while matches!(chars.peek(), Some(c) if c.is_whitespace() || *c == ',') {
            chars.next();
        }
        match chars.next() {
            None => break,
            Some('"') => {
                let mut cur = String::new();
                loop {
                    match chars.next()? {
                        '"' => break,
                        '\\' => match chars.next()? {
                            'n' => cur.push('\n'),
                            't' => cur.push('\t'),
                            'r' => cur.push('\r'),
                            'u' => {
                                let hex: String = (0..4).filter_map(|_| chars.next()).collect();
                                let code = u32::from_str_radix(&hex, 16).ok()?;
                                cur.push(char::from_u32(code).unwrap_or('\u{FFFD}'));
                            }
                            other => cur.push(other),
                        },
                        c => cur.push(c),
                    }
                }
                out.push(cur);
            }
            Some(_) => return None,
        }
    }
    Some(out)
}

fn parse_urls(blob: &str) -> Vec<String> {
    let items: Vec<String> = match parse_json_string_array(blob) {
        Some(v) => v,
        None => blob
            .split(|c| c == '\n' || c == ',')
            .map(|s| s.to_string())
            .collect(),
    };
    let mut out: Vec<String> = Vec::new();
    for item in items {
        let t = item.trim();
        if t.is_empty() || t.starts_with('#') {
            continue;
        }
        if !(t.starts_with("https://") || t.starts_with("http://")) {
            continue;
        }
        if !out.iter().any(|u| u == t) {
            out.push(t.to_string());
        }
    }
    out
}

impl Guest for Node {
    fn run(_info: RunInfo) -> SubscriptionList {
        // Only authority: `get` on the 'subscriptions' store. Never fabricate
        // URLs; return exactly what the store holds.
        let mut urls = Vec::new();
        for key in ["urls", "subscriptions", "feeds"] {
            if let Some(blob) = state_read::get(key) {
                urls = parse_urls(&blob);
                if !urls.is_empty() {
                    break;
                }
            }
        }
        SubscriptionList { urls }
    }
}

export!(Node);
```

